const e="mexique",l=1,s={habitants:"les Mexicains",adjectif:"mexicain",adjectifF:"mexicaine",devise:"Del pueblo, para el pueblo, pendant quatre heures et avec questions.",medaillon:"MX",chaineInfo:"MX NOTICIAS",hymne:"Mexicains, au cri de guerre : encore une conférence"},n={chambre:"Congrès",chambreLong:"Congrès de l’Union",chefGouvernement:"Président de la République",chefEtat:"Président de la République",passageForce:{label:"Initiative préférente",description:"Le président déclare un projet « prioritaire » et le Congrès doit le traiter en quelques sessions. L’opposition parle d’un rouleau compresseur, la majorité d’un rouleau de printemps.",news:"Initiative préférente : « {loi} » est inscrit en priorité, les commissions s’exécutent"},censure:{label:"Jugement politique",description:"La Chambre peut mettre en cause un haut responsable et le Sénat en juge. La procédure est solennelle, rarement conclue et souvent animée par des banderoles.",news:"Jugement politique : le Congrès brandit des banderoles contre l’exécutif"},dissolution:{label:"Consultation populaire",description:"Le président convoque une consultation nationale pour légitimer un projet. Le Congrès n’est pas dissous, mais il apprend à ne pas se faire remarquer.",news:"Consultation populaire : le pays vote sur une question à rallonge"}},a={type:"presidentielle",label:"Élection présidentielle",intro:"Six ans pour un seul mandat et une campagne qui commence la veille de l’investiture. Les affiches couvrent les murs, les chansons de campagne couvrent les affiches, et chacun connaît déjà le nom du futur favori.",adversaires:[{id:"rodrigo-salvatierra",name:"Rodrigo Salvatierra",parti:"Action Nationale Démocratique",style:"chiffres",punchlines:["Ils promettent de l’eau pour tout le monde, mais ils n’ont même pas de plan pour le robinet.","Les chiffres de la sécurité disent une chose, les rues en disent une autre. Faites confiance à votre rue.","L’investissement étranger revient quand l’État arrête d’annoncer des projets à la télévision."],genre:"m"},{id:"lucia-montenegro",name:"Lucía Montenegro",parti:"Mouvement Citoyen Libre",style:"emotion",punchlines:["Je suis jeune, je viens de la ville et je n’ai pas peur de dire que l’eau est un droit.","Pour les mères, pour les enfants, pour les robinets : voilà trois raisons de changer.","Ils parlent du peuple, moi je parle avec le peuple, c’est plus long."]},{id:"esteban-quiroga",name:"Esteban Quiroga",parti:"Parti Révolutionnaire Institutionnel",style:"esquive",punchlines:["Mon parti a gouverné, perdu, gouverné de nouveau. Nous avons l’expérience de l’alternance.","Nous sommes pour la stabilité, c’est-à-dire pour nous.","Je ne ferai pas de promesses, j’en ai déjà trop tenu dans le passé."],genre:"m"}],nuitElectorale:"Le décompte avance par États, et chaque chaîne annonce une victoire différente. Dans le Zócalo, les drapeaux s’agitent pendant que la commission électorale s’éclaircit la voix."},i=[{id:"mexique-reforme-eau-capitale",title:"Plan hydrique de la vallée de Mexico",domain:"ecologie",description:"Réparer les fuites d’un réseau qui perd un litre sur trois, forer plus profond et convaincre les robinets de la capitale de coopérer. La vallée s’enfonce, le plan aussi.",accroche:"La ville enfoncée cherche l'eau, et elle trouvera surtout des comités de bassin.",effects:{ecologie:4,cohesion:3,budget:-6,popularite:1},delayed:[{delay:3,effects:{ecologie:2,cohesion:2},label:"Moins de fuites, plus de pression"},{delay:4,effects:{popularite:1},label:"Quartiers raccordés"}],groupStance:{"morena-renovacion":.7,"accion-nacional":.2,"revolucionario-inst":.3,"verde-ecologista":.8,"movimiento-ciudadano":.5,"trabajo-unidos":.8},streetAnger:.2},{id:"mexique-garde-nationale-civile",title:"Réforme de la Garde nationale",domain:"securite",description:"Placer la Garde nationale sous tutelle civile, ou sous tutelle militaire, selon l’orateur. Le texte tient en deux versions, qui s’affrontent poliment.",accroche:"Une garde plus civile, avec un uniforme que même le mariachi pourrait approuver.",effects:{securite:5,cohesion:-2,budget:-5,international:-1},delayed:[{delay:3,effects:{securite:2},label:"Présence renforcée dans les régions"}],groupStance:{"morena-renovacion":.6,"accion-nacional":.5,"revolucionario-inst":.3,"verde-ecologista":.1,"movimiento-ciudadano":-.6,"trabajo-unidos":-.4},streetAnger:.4},{id:"mexique-salaire-minimum-revalo",title:"Revalorisation du salaire minimum",domain:"travail",description:"Un salaire minimum qui grimpe plus vite que l’inflation, ce qui est rare. Les entreprises réclament un délai de transition, les travailleurs réclament que le délai soit court.",accroche:"Le salaire monte, le prix des tacos observe l'ascenseur avec un œil de lynx.",effects:{pouvoirAchat:5,cohesion:2,economie:-2,budget:-1},delayed:[{delay:3,effects:{pouvoirAchat:2,popularite:2},label:"Pouvoir d’achat en hausse"},{delay:4,effects:{economie:-1},label:"Embauches en berne"}],groupStance:{"morena-renovacion":.9,"accion-nacional":-.7,"revolucionario-inst":-.3,"verde-ecologista":.5,"movimiento-ciudadano":.4,"trabajo-unidos":1},streetAnger:.2},{id:"mexique-maiz-souverainete",title:"Loi de souveraineté du maïs",domain:"agriculture",description:"Protéger le maïs traditionnel contre les variétés importées et les contrats dont personne ne comprend les clauses en petits caractères. La tortilla devient politique.",accroche:"Le maïs est souverain, la tortilla l'a su avant tout le monde.",effects:{cohesion:3,ecologie:2,economie:-2,international:-2},delayed:[{delay:3,effects:{cohesion:2,popularite:2},label:"Petits producteurs rassurés"}],groupStance:{"morena-renovacion":.8,"accion-nacional":-.3,"revolucionario-inst":.5,"verde-ecologista":.9,"movimiento-ciudadano":.1,"trabajo-unidos":.4},streetAnger:.1},{id:"mexique-nearshoring-parcs",title:"Parcs industriels de relocalisation",domain:"travail",description:"Offrir terrain, eau et énergie aux usines qui quittent l’Asie pour se rapprocher du voisin du nord. L’eau est déjà demandée par trois villes et une rivière.",accroche:"Les usines viennent plus près, et les camions disent adieu à la carte routière.",effects:{economie:6,budget:-4,ecologie:-3,international:2},delayed:[{delay:3,effects:{economie:3,pouvoirAchat:1},label:"Emplois créés dans le nord"},{delay:4,effects:{ecologie:-1,cohesion:-1},label:"Tensions autour de l’eau"}],groupStance:{"morena-renovacion":.4,"accion-nacional":.9,"revolucionario-inst":.5,"verde-ecologista":-.5,"movimiento-ciudadano":.5,"trabajo-unidos":-.3},streetAnger:.3},{id:"mexique-petrole-national",title:"Recapitalisation de la compagnie pétrolière nationale",domain:"energie",description:"Renflouer la compagnie nationale, fierté du pays et gouffre de son budget. La compagnie remercie l’État en promettant de forer encore plus profond.",accroche:"La compagnie nationale se refait une santé, avec le brillant d'un vieux puits.",effects:{economie:2,budget:-6,ecologie:-4,cohesion:2},delayed:[{delay:3,effects:{economie:1,budget:1},label:"Production stabilisée"}],groupStance:{"morena-renovacion":.9,"accion-nacional":-.5,"revolucionario-inst":.3,"verde-ecologista":-.4,"movimiento-ciudadano":-.1,"trabajo-unidos":.4},streetAnger:.3},{id:"mexique-sante-universelle-imss",title:"Système de santé unifié",domain:"sante",description:"Fusionner les caisses pour que chaque Mexicain ait accès aux mêmes soins, du moins sur le papier. Les médecins arrivent, les médicaments moins vite.",accroche:"Un système unique de santé, avec un seul numéro de file et sept guichets pour le deviner.",effects:{cohesion:4,pouvoirAchat:2,budget:-6,popularite:1},delayed:[{delay:4,effects:{cohesion:3,popularite:1},label:"Plus de centres de santé ouverts"}],groupStance:{"morena-renovacion":.9,"accion-nacional":-.3,"revolucionario-inst":.2,"verde-ecologista":.4,"movimiento-ciudadano":.6,"trabajo-unidos":.7},streetAnger:.2},{id:"mexique-tourisme-train-sud",title:"Train touristique du Sud-Est",domain:"travail",description:"Un train à travers la jungle pour relier plages, ruines et touristes. Les archéologues, les environnementalistes et les chauffeurs de taxi ont ouvert un dossier chacun.",accroche:"Le train traverse la jungle, et le jaguar demande déjà un siège côté fenêtre.",effects:{economie:4,cohesion:1,budget:-6,ecologie:-3},delayed:[{delay:4,effects:{economie:2,popularite:2},label:"Premières rames inaugurées"},{delay:3,effects:{ecologie:-1},label:"Critiques de riverains"}],groupStance:{"morena-renovacion":.9,"accion-nacional":-.2,"revolucionario-inst":.2,"verde-ecologista":-.4,"movimiento-ciudadano":.2,"trabajo-unidos":.3},streetAnger:.2},{id:"mexique-remesses-simplification",title:"Facilitation des envois de fonds familiaux",domain:"travail",description:"Moins de frais sur les virements de ceux qui travaillent au nord et envoient de l’argent aux leurs. Les banques perdent des commissions, les familles perdent un peu moins.",accroche:"L'argent de la famille arrive sans frais, juste avec trois appels de la tante.",effects:{pouvoirAchat:4,cohesion:2,economie:1,budget:-1},delayed:[{delay:3,effects:{pouvoirAchat:2,international:1},label:"Familles bénéficiaires plus nombreuses"}],groupStance:{"morena-renovacion":.7,"accion-nacional":.3,"revolucionario-inst":.4,"verde-ecologista":.2,"movimiento-ciudadano":.5,"trabajo-unidos":.6},streetAnger:.1},{id:"mexique-matinale-transparence",title:"Loi sur les conférences quotidiennes",domain:"institutions",description:"Encadrer les longues conférences de presse du matin : durée maximale de deux heures, interdiction des sketches. L’opposition réclame trois heures de plus pour le droit de réponse.",accroche:"La conférence quotidienne devient obligatoire, les silences devront prendre rendez-vous.",effects:{assemblee:-2,popularite:-2,cohesion:3},delayed:[{delay:3,effects:{popularite:1,assemblee:1},label:"Débat public plus lisible"}],groupStance:{"morena-renovacion":-.7,"accion-nacional":.7,"revolucionario-inst":.2,"verde-ecologista":.1,"movimiento-ciudadano":.8,"trabajo-unidos":-.4},streetAnger:.1}],t=[{id:"mexique-secheresse-capitale",title:"Sécheresse à Mexico",category:"climat",description:"Les réservoirs tombent à un niveau que les cartes officielles préfèrent ne pas afficher. Dans la capitale, le robinet fait des pauses, les camions-citernes font des heures supplémentaires et la pluie fait la grève.",weight:7,minTurn:3,conditions:[{gauge:"ecologie",op:"<",value:52}],choices:[{id:"rationnement",label:"Imposer un rationnement par quartiers",description:"Couper l’eau à tour de rôle, avec un calendrier de rotation.",effects:{ecologie:3,cohesion:-3,popularite:-4,budget:-2},delayed:[{delay:3,effects:{ecologie:1},label:"Réserves partiellement reconstituées"}],news:"Rationnement : l’eau coule le mardi dans le nord, le jeudi dans le sud"},{id:"camions-citernes",label:"Multiplier les camions-citernes",description:"Livrer l’eau dans les quartiers sans robinet.",effects:{cohesion:4,popularite:2,budget:-5},delayed:[{delay:3,effects:{popularite:-1,budget:-2},label:"Coût des livraisons"}],news:"Mexico : des centaines de camions-citernes dans les rues"},{id:"infrastructure",label:"Lancer un grand chantier hydrique",description:"Aqueducs, forages et promesses de long terme.",effects:{ecologie:2,economie:1,budget:-6,popularite:1},delayed:[{delay:4,effects:{ecologie:2,cohesion:2},label:"Premières fuites réparées"}],news:"Grand chantier hydrique : un aqueduc, des conférences et un ruban à couper"}]},{id:"mexique-seisme-capitale",title:"Séisme à Mexico",category:"climat",description:"Le sol bouge à 7 heures du matin, l’alarme sonne, les habitants sortent en chaussettes. Plusieurs immeubles s’effondrent, des brigades de volontaires se forment en quelques minutes.",weight:5,minTurn:4,once:!0,choices:[{id:"secours-nationaux",label:"Mobiliser tous les secours et l’armée",description:"Déblayer, fouiller, soigner, dans cet ordre.",effects:{securite:3,cohesion:4,budget:-6,popularite:3},delayed:[{delay:3,effects:{cohesion:2},label:"Solidarité nationale"}],news:"Séisme : volontaires et soldats travaillent côte à côte"},{id:"normes",label:"Annoncer un audit des normes de construction",description:"Savoir quels immeubles tiendraient au prochain.",effects:{securite:2,cohesion:1,budget:-3,economie:-2,popularite:-1},delayed:[{delay:4,effects:{securite:2},label:"Immeubles sécurisés"}],news:"Audit des immeubles : quelques promoteurs changent de téléphone"},{id:"minimal",label:"Laisser la ville gérer",description:"Déléguer au gouvernement local.",effects:{popularite:-5,cohesion:-3,budget:1},news:"Séisme : l’exécutif fédéral « appuie » depuis une conférence"}]},{id:"mexique-cartel-violence-region",title:"Flambée de violence dans une région",category:"securite",description:"Des groupes criminels affrontent la police dans un État du nord. Des routes sont bloquées, des écoles ferment, des communiqués se contredisent en trois langues.",weight:7,minTurn:3,conditions:[{gauge:"securite",op:"<",value:50}],choices:[{id:"deploiement",label:"Déployer des unités spéciales",description:"Reprendre le contrôle du terrain.",effects:{securite:4,cohesion:-2,budget:-5,popularite:-1},delayed:[{delay:3,effects:{cohesion:-1},label:"Accusations d’abus"}],chain:{crisisId:"mexique-abus-forces-ordre",probability:.3,delay:2},news:"Unités spéciales envoyées : les routes rouvrent, les rumeurs aussi"},{id:"social",label:"Parier sur les programmes sociaux",description:"Bourses, emplois pour les jeunes et centres culturels.",effects:{cohesion:3,pouvoirAchat:1,budget:-5,securite:-1},delayed:[{delay:4,effects:{securite:2,cohesion:2},label:"Moins de recrutement par les groupes"}],news:"Programmes sociaux pour les jeunes : « des câlins plutôt que des balles », dit l’opposition"},{id:"negociation",label:"Ouvrir un dialogue avec les élus locaux",description:"Réunir maires et gouverneurs.",effects:{cohesion:2,assemblee:2,securite:1,popularite:-1},news:"Sommet sécurité : maires et gouverneurs signent une déclaration"}]},{id:"mexique-abus-forces-ordre",title:"Accusations d’abus des forces de l’ordre",category:"securite",description:"Une vidéo montre des agents dépassant leurs compétences. Les associations demandent une enquête, la chaîne d’information en continue demande des images supplémentaires.",weight:5,chainOnly:!0,choices:[{id:"enquete",label:"Ouvrir une enquête indépendante",description:"Sanctionner les fautifs et rassurer.",effects:{cohesion:3,international:2,popularite:1,securite:-1},news:"Enquête indépendante : la vidéo est l’exposé numéro un"},{id:"defendre",label:"Défendre les unités",description:"Rappeler que le terrain est complexe.",effects:{securite:1,popularite:-3,international:-3,cohesion:-2},news:"L’exécutif défend ses agents, les associations haussent le ton"}]},{id:"mexique-conference-matinale-derape",title:"Une conférence matinale qui déborde",category:"politique",description:"La conférence de presse quotidienne dure quatre heures, aborde sept sujets, trois polémiques et une recette de mole. Les agendas ministériels sont reportés sine die.",weight:5,minTurn:3,choices:[{id:"assumer",label:"Assumer et faire le tour de la presse",description:"Continuer à répondre à tout, y compris aux questions qui n’en sont pas.",effects:{popularite:2,assemblee:-1,cohesion:1,economie:-1},delayed:[{delay:3,effects:{popularite:-2},label:"Fatigue de l’auditoire"}],news:"Conférence de quatre heures : record de durée, record d’audience"},{id:"raccourcir",label:"Raccourcir et se concentrer",description:"Fixer une heure, un sujet et un sablier.",effects:{cohesion:2,assemblee:2,popularite:-1},news:"Conférence matinale : une heure chrono, l’audience est déçue"},{id:"invite",label:"Inviter un ministre à répondre",description:"Déléguer la parole sans la perdre.",effects:{assemblee:1,popularite:-1,cohesion:1},news:"Un ministre prend la parole, le président le regarde de loin"}]},{id:"mexique-ouragan-pacifique",title:"Ouragan sur la côte du Pacifique",category:"climat",description:"Un ouragan frappe un port touristique, arrache les parasols, soulève les yachts et fait trembler les promesses de tourisme durable. Les hôtels ferment, les pêcheurs aussi.",weight:5,minTurn:4,choices:[{id:"reconstruction",label:"Lancer un plan de reconstruction",description:"Réparer les ports et indemniser les pêcheurs.",effects:{cohesion:3,economie:1,budget:-6,popularite:2},delayed:[{delay:4,effects:{economie:2},label:"Tourisme de retour"}],news:"Ouragan : le plan de reconstruction est signé sur un parasol récupéré"},{id:"militaires",label:"Envoyer l’armée au secours",description:"Évacuer, ravitailler, réparer.",effects:{securite:2,cohesion:3,budget:-4,popularite:1},news:"L’armée distribue eau et couvertures dans la zone sinistrée"},{id:"assurance-l",label:"S’en remettre aux assureurs",description:"Un communiqué de compassion et un numéro vert.",effects:{popularite:-4,cohesion:-2,budget:1},news:"Ouragan : l’exécutif « suit la situation depuis sa conférence »"}]},{id:"mexique-tension-frontiere-nord",title:"Tension avec le voisin du nord",category:"international",description:"Le voisin du nord menace de relever les droits de douane, de durcir les contrôles et de convoquer une conférence qui durerait des mois. Les camions font la queue sur dix kilomètres.",weight:5,minTurn:4,choices:[{id:"negocier-voisin",label:"Négocier un accord de coopération",description:"Plus de contrôle sur la frontière, moins de droits de douane.",effects:{international:3,economie:3,securite:1,popularite:-2},delayed:[{delay:3,effects:{economie:2},label:"Flux commerciaux rétablis"}],news:"Accord frontalier : les camions avancent, les orateurs aussi"},{id:"fermete",label:"Rappeler la souveraineté nationale",description:"Un discours vibrant sur la dignité et le maïs.",effects:{popularite:3,international:-4,economie:-2,cohesion:2},delayed:[{delay:3,effects:{economie:-2},label:"Droits de douane relevés"}],news:"Souveraineté : le président répond, le voisin répond à la réponse"},{id:"commission",label:"Constituer une commission bilatérale",description:"Un joyau d’ingénierie diplomatique : deux salles, trois traducteurs, aucun résultat.",effects:{international:1,popularite:-1,economie:-1},delayed:[{delay:3,effects:{economie:1},label:"Premières mesures techniques"}],news:"Commission bilatérale : première réunion, deuxième café"}]}],r=[{id:"mexique-eau-capitale-mission",title:"Garder l’eau courante à Mexico",brief:"Un indice d’écologie à 50 : assez pour que les robinets coulent plus longtemps que les discours sur les robinets.",objective:{type:"gaugeAtLeast",gauge:"ecologie",value:50},reward:{ecologie:2,cohesion:1},news:"Mexico : le robinet coule, la presse en rend compte avec émotion"},{id:"mexique-securite-regions",title:"Reprendre pied dans les régions",brief:"Gagner quatre points de sécurité sans que personne n’explique que c’était déjà prévu.",objective:{type:"gaugeGain",gauge:"securite",value:4},reward:{securite:2,popularite:1},news:"Sécurité : les chiffres s’améliorent, les rumeurs aussi"},{id:"mexique-conference-sans-derapage",title:"Une semaine de conférences sans dérapage",brief:"Aucune jauge dans le rouge : une semaine sans polémique matinale, record envisageable.",objective:{type:"noRedGauge"},reward:{popularite:1,cohesion:1,assemblee:1},news:"Conférences matinales : une semaine sans incident, la presse s’interroge"},{id:"mexique-crise-maitrisee",title:"Gérer une crise avec calme",brief:"Gérer une crise sans que le calendrier des conférences n’en souffre. Les lecteurs jugeront du calme.",objective:{type:"crisisWell"},reward:{popularite:2,securite:1},news:"Crise maîtrisée : le palais national organise une conférence pour le dire"}],o=JSON.parse('{"medias":["La Gaceta del Valle","Radio Tianguis","Canal Sol Naciente","El Heraldo del Zócalo","Noticias de la Sobremesa"],"journalistes":[{"id":"mexique-j-renata-escobedo","name":"Renata Escobedo Villaseñor","media":"La Gaceta del Valle","style":"incisive : pose la question qui fâche avec un sourire de marraine de mariage"},{"id":"mexique-j-gonzalo-ibarra","name":"Gonzalo Ibarra Cuéllar","media":"Radio Tianguis","style":"bavard : annonce « une dernière question » depuis quarante minutes","genre":"m"},{"id":"mexique-j-ximena-arriaga","name":"Ximena Arriaga Pons","media":"Canal Sol Naciente","style":"méthodique : arrive avec un classeur, repart avec trois","genre":"f"},{"id":"mexique-j-ildefonso-tovar","name":"Ildefonso Tovar Bermúdez","media":"El Heraldo del Zócalo","style":"nostalgique : compare tout à l’époque où les crises avaient de la classe"},{"id":"mexique-j-marisol-quintanar","name":"Marisol Quintanar Ledesma","media":"Noticias de la Sobremesa","style":"gourmande : lie chaque dossier à un plat, de préférence épicé","genre":"f"},{"id":"mexique-j-teodoro-baca","name":"Teodoro Baca Montaño","media":"La Gaceta del Valle","style":"sceptique : lève un sourcil dès que le mot « plan » est prononcé"},{"id":"mexique-j-citlali-menchaca","name":"Citlali Menchaca Rueda","media":"Radio Tianguis","style":"pétillante : pose des questions en rafale, sans reprendre son souffle","genre":"f"},{"id":"mexique-j-anselmo-duarte","name":"Anselmo Duarte Lozano","media":"El Heraldo del Zócalo","style":"solennel : parle du pays comme d’un monument qu’il aurait personnellement élevé","genre":"m"}],"questions":[{"id":"mexique-q-popularite-conference-quatre-heures","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Chef de l’État, votre conférence matinale dure quatre heures, et les sondages baissent plus vite que le café ne refroidit. Faut-il y voir un lien de cause à effet ?","answers":[{"tone":"franche","label":"Il y a peut-être un lien. Je vais raccourcir, et mieux préparer mes réponses : le peuple mérite des idées, pas seulement de la durée.","effects":{"popularite":5,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les partisans regrettent le format fleuve"}],"news":"Le président promet une conférence « plus courte, mais pas trop »"},{"tone":"langue-de-bois","label":"Le dialogue avec le peuple n’a pas de durée. Il a une profondeur, et la profondeur se mesure en heures, parfois en bâillements.","effects":{"popularite":2,"economie":-2},"news":"Conférence matinale : le président défend la « profondeur » du temps"},{"tone":"offensive","label":"Quatre heures, c’est ce qu’il faut pour répondre à des questions qui en méritent dix. Ceux qui partent avant la fin n’aiment pas la démocratie.","effects":{"popularite":4,"international":-3,"cohesion":-3},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"La presse boude les prochaines conférences"}],"news":"Le président fustige les journalistes qui quittent la salle"}]},{"id":"mexique-q-popularite-fresque-ovation","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":45},"text":"Dans un village, une fresque vous représente en héros. Dans le village voisin, une autre vous représente en gros plan sur un grille-pain. Quel mur préférez-vous ?","answers":[{"tone":"franche","label":"Le grille-pain. Il est chaud le matin, il fait tourner la maison, et on lui demande peu d’explications. C’est un modèle de gouvernement.","effects":{"popularite":4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Le village du héros se vexe puis se réconcilie"}],"news":"Le président préfère la fresque du grille-pain à celle du héros"},{"tone":"langue-de-bois","label":"Je suis touché par toutes les formes d’expression populaire, quelle qu’en soit la couleur. L’art mural est le miroir de notre démocratie.","effects":{"popularite":2,"economie":-2},"news":"Fresques : le président salue « le miroir de la démocratie »"},{"tone":"offensive","label":"Les murs n’ont jamais voté. Je préfère les électeurs aux peintres, et je souhaite que les peintres commencent par payer leurs échafaudages.","effects":{"popularite":4,"international":-2,"assemblee":-3},"news":"Le président tacle les muralistes sur leurs échafaudages"}]},{"id":"mexique-q-popularite-sommet-aimes","theme":"popularite","condition":{"gauge":"popularite","op":">","value":65},"text":"Votre cote est au sommet, et les cantines des ministères vendent des tasses à votre effigie. N’avez-vous pas peur de vous croire intouchable ?","answers":[{"tone":"franche","label":"Si. Je garde une tasse sur mon bureau pour me rappeler qu’on casse vite ce qu’on aime trop. Les sondages, eux aussi, se brisent.","effects":{"popularite":3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Le sens de l’humilité plaît en haut comme en bas"}],"news":"« Je garde une tasse sur mon bureau » : le président se méfie des sondages"},{"tone":"langue-de-bois","label":"La popularité est un prêt, pas un cadeau. Je compte la rembourser en résultats, et je demande qu’on ne m’envoie pas la facture trop tôt.","effects":{"popularite":2,"budget":-2},"news":"Le président compare sa popularité à un prêt remboursable"},{"tone":"offensive","label":"Intouchable ? Je ne le suis pas, mais ceux qui critiquent mes tasses sont priés de fournir de meilleures tasses, avec de meilleures anses.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"L’opposition lance « la grande affaire des anses »"}],"news":"Le président défie ses critiques : « Fournissez de meilleures tasses »"}]},{"id":"mexique-q-economie-voisin-du-nord","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Quand le grand voisin du nord éternue, l’industrie du pays s’enrhume. Comptez-vous enfin vous acheter un mouchoir ou continuer à emprunter le sien ?","answers":[{"tone":"franche","label":"Il faut diversifier : plus de partenaires, plus de transformations sur place. Cela prendra des années, mais le mouchoir est déjà au catalogue.","effects":{"economie":4,"international":-2,"budget":-2},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Premiers contrats avec de nouveaux partenaires"}],"news":"Économie : le président veut « un mouchoir au catalogue »"},{"tone":"langue-de-bois","label":"Notre relation avec nos voisins est un partenariat stratégique et équilibré, appelé à se renforcer dans le respect mutuel et dans les deux sens.","effects":{"economie":2,"popularite":-2},"news":"Le président parle de partenariat « dans les deux sens »"},{"tone":"offensive","label":"Ce mouchoir, nous le tisserons ici, avec des ouvriers d’ici. Que les usines viennent à nous, ou qu’elles nous expliquent pourquoi elles partent.","effects":{"economie":5,"international":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"economie":-3},"label":"Des investisseurs mettent leurs projets en pause"}],"news":"Le président somme les usines étrangères de rester ou de s’expliquer"}]},{"id":"mexique-q-economie-remesas-record","theme":"economie","condition":{"gauge":"economie","op":">","value":60},"text":"Les envois d’argent des familles installées au nord battent un record. Ce record est-il une victoire du gouvernement, ou la preuve qu’on gagne mieux sa vie en partant ?","answers":[{"tone":"franche","label":"C’est d’abord le travail de ces familles, que je salue. Mon devoir est de faire en sorte que partir soit un choix et non une obligation.","effects":{"popularite":4,"budget":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les familles apprécient d’être remerciées plutôt que comptabilisées"}],"news":"Envois de fonds : « Partir doit rester un choix », dit le président"},{"tone":"langue-de-bois","label":"Les transferts témoignent de la solidité des liens familiaux et de la vitalité de notre diaspora, que nous continuerons d’accompagner.","effects":{"economie":2,"popularite":-2},"news":"Le président salue la « vitalité » de la diaspora"},{"tone":"offensive","label":"Mon gouvernement a rendu ce record possible par la stabilité, et je ne vois pas qui d’autre aurait pu y penser. Les critiques n’envoient pas un centime.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Des familles s’étonnent d’être un argument de campagne"}],"news":"Le président s’attribue le record des envois de fonds"}]},{"id":"mexique-q-budget-compagnie-petroliere","theme":"budget","condition":{"gauge":"budget","op":"<","value":40},"text":"La compagnie pétrolière nationale réclame un nouveau milliard pour « consolider ses fondations ». Vos caisses, elles, consolident surtout leurs courants d’air. Qui paie ?","answers":[{"tone":"franche","label":"Nous financerons ce qui est indispensable, pas davantage. La compagnie recevra un plan d’efficacité avant tout chèque, et les rapports seront publics.","effects":{"budget":4,"economie":-2,"assemblee":-2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"La compagnie présente un plan de réduction des pertes"}],"news":"Pétrole : le président met des conditions à l’aide à la compagnie"},{"tone":"langue-de-bois","label":"La compagnie est un joyau national qui doit continuer à rayonner. Le budget fera ce qu’il faut, dans la mesure de ses moyens et de ses espoirs.","effects":{"economie":2,"budget":-3},"news":"Le président qualifie la compagnie pétrolière de « joyau »"},{"tone":"offensive","label":"Si l’on met la compagnie en vitrine pour demander des milliards, qu’on la mette aussi en vitrine pour rendre des comptes. Pas un sou sans audit.","effects":{"budget":5,"popularite":2,"assemblee":-4},"news":"Le président réclame un audit complet avant de signer le chèque"}]},{"id":"mexique-q-pouvoir-achat-tortilla","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":40},"text":"La tortilla est le thermomètre de chaque foyer, et le thermomètre affiche de la fièvre. Que dites-vous aux familles qui comptent leurs tortillas avant de les manger ?","answers":[{"tone":"franche","label":"Je comprends l’angoisse. Nous allons plafonner le prix du maïs de base et surveiller les intermédiaires, quitte à en froisser quelques-uns.","effects":{"pouvoirAchat":5,"economie":-2,"budget":-2},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Des minotiers menacent de réduire la production"}],"news":"Le président promet de plafonner le prix du maïs de base"},{"tone":"langue-de-bois","label":"Le gouvernement suit de près l’évolution des prix de la tortilla, qui reste, au cœur de notre culture, un symbole d’unité et de rondeur.","effects":{"pouvoirAchat":2,"popularite":-3},"news":"Prix de la tortilla : le gouvernement « suit de près »"},{"tone":"offensive","label":"Ceux qui spéculent sur la tortilla s’attaquent à l’assiette du peuple. Nous les poursuivrons, et leurs entrepôts apprendront à ouvrir leurs portes.","effects":{"pouvoirAchat":5,"economie":-3,"international":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les foules applaudissent les contrôles dans les marchés"}],"news":"Le président promet de « faire ouvrir les entrepôts » des spéculateurs"}]},{"id":"mexique-q-pouvoir-achat-salaire-minimum","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":">","value":55},"text":"Le salaire minimum a grimpé plus vite que les prix, ce qui est rare. Les patrons de petites entreprises parlent de « miracle fragile ». Peut-on continuer ainsi ?","answers":[{"tone":"franche","label":"Oui, mais pas sans l’accompagnement des petites entreprises. Nous aiderons celles qui n’ont pas les reins solides, avec des délais et des crédits.","effects":{"pouvoirAchat":3,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les petites entreprises encaissent la hausse sans fermer"}],"news":"Salaire minimum : le président annonce des aides aux petites entreprises"},{"tone":"langue-de-bois","label":"Le salaire minimum progresse de manière responsable. La stabilité des prix demeure un objectif de long terme, comme la plupart des objectifs.","effects":{"pouvoirAchat":2,"economie":-2},"news":"Le président promet « une progression responsable » des salaires"},{"tone":"offensive","label":"Un miracle n’est fragile que pour ceux qui n’y croient pas. Les patrons sauront faire de la place dans leurs marges, ou dans leurs voitures de fonction.","effects":{"pouvoirAchat":5,"popularite":2,"economie":-4,"cohesion":-2},"news":"Le président aux patrons : « Cherchez dans vos marges »"}]},{"id":"mexique-q-securite-violence-regions","theme":"securite","condition":{"gauge":"securite","op":"<","value":40},"text":"Dans plusieurs régions, des familles vivent avec la peur et pleurent des proches disparus. Vos mesures sont-elles à la hauteur, ou l’État arrive-t-il toujours après ?","answers":[{"tone":"franche","label":"Pas encore. Les victimes et leurs familles méritent la vérité et la présence de l’État. Nous renforcerons les enquêtes, avec elles, pas sans elles.","effects":{"securite":4,"popularite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"securite":2},"label":"Des cellules d’enquête locales entrent en service"}],"news":"Violence : le président reconnaît que l’État n’est « pas encore à la hauteur »"},{"tone":"langue-de-bois","label":"La sécurité est un défi complexe, qui exige une approche globale, durable et coordonnée entre tous les niveaux de gouvernement et la société.","effects":{"securite":2,"popularite":-3},"news":"Sécurité : le président plaide pour une « approche globale »"},{"tone":"offensive","label":"Je ne laisserai pas les réseaux criminels dicter leur loi. Nous renforcerons la présence de la Garde nationale partout où l’État a reculé, même si cela coûte.","effects":{"securite":5,"budget":-4,"cohesion":-3},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Des associations s’inquiètent des droits de l’homme"}],"news":"Le président annonce un renfort de la Garde nationale dans les zones sensibles"}]},{"id":"mexique-q-securite-baisse-homicides","theme":"securite","condition":{"gauge":"securite","op":">","value":60},"text":"Les statistiques de la sécurité s’améliorent. Les habitants des régions les plus touchées y croient-ils, ou faut-il leur envoyer des chiffres avec le courrier ?","answers":[{"tone":"franche","label":"Les chiffres ne consolent personne. Je veux que chaque famille touchée constate la différence dans sa rue, pas dans un tableau.","effects":{"popularite":4,"budget":-3},"delayed":[{"delay":2,"effects":{"securite":2},"label":"Les patrouilles de proximité se multiplient"}],"news":"Le président : « Je ne veux pas de chiffres, je veux des rues calmes »"},{"tone":"langue-de-bois","label":"Les résultats montrent que notre stratégie fonctionne. La prudence reste de mise, car un mois favorable ne fait pas un printemps.","effects":{"securite":2,"popularite":-2},"news":"Le président : « Un mois favorable ne fait pas un printemps »"},{"tone":"offensive","label":"Ceux qui doutent des chiffres sont ceux qui n’aiment pas les bonnes nouvelles. Je les invite à venir constater, sans caméra, ce qu’ils refusent de voir.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"news":"Le président invite ses détracteurs à « constater sans caméra »"}]},{"id":"mexique-q-cohesion-nord-sud","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":40},"text":"Le nord industriel et le sud rural se renvoient la balle : l’un dit financer l’autre, l’autre dit nourrir l’un. Qui a raison, selon vous ?","answers":[{"tone":"franche","label":"Ils ont raison tous les deux, et ils ont tort de s’opposer. Les régions du sud ont été oubliées trop longtemps : un plan d’investissement est nécessaire.","effects":{"cohesion":4,"budget":-3,"economie":-2},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les chantiers du sud créent des emplois locaux"}],"news":"Le président annonce un plan d’investissement pour le sud"},{"tone":"langue-de-bois","label":"Le pays est un tout, et ses régions sont complémentaires. Chaque territoire contribue à sa manière à l’effort commun, et reçoit selon ses besoins.","effects":{"cohesion":2,"popularite":-2},"news":"Le président : « Chaque territoire contribue à sa manière »"},{"tone":"offensive","label":"Que le nord cesse de compter, et que le sud cesse de se plaindre. Un pays qui calcule ses cousins ne fait plus famille.","effects":{"popularite":3,"cohesion":-2,"economie":-3},"news":"Le président : « Un pays qui compte ses cousins ne fait plus famille »"}]},{"id":"mexique-q-ecologie-eau-capitale","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":40},"text":"La vallée de la capitale s’enfonce de quelques centimètres par an et les robinets des quartiers périphériques crachotent. À quand une ville qui ne boit pas son propre sol ?","answers":[{"tone":"franche","label":"Il faut réparer le réseau avant de forer plus profond. Nous consacrons l’essentiel du plan aux fuites, même si c’est moins spectaculaire qu’un grand tunnel.","effects":{"ecologie":5,"budget":-4,"popularite":-2},"delayed":[{"delay":3,"effects":{"ecologie":2,"pouvoirAchat":1},"label":"Moins de fuites, plus de pression dans les quartiers"}],"news":"Eau : le président mise sur les fuites plutôt que sur un grand tunnel"},{"tone":"langue-de-bois","label":"L’eau est un droit et une responsabilité partagée. Un comité d’experts étudiera des solutions de long terme, au rythme qu’exige l’eau, c’est-à-dire lentement.","effects":{"ecologie":2,"popularite":-3},"news":"Un comité sur l’eau, des solutions « à long terme »"},{"tone":"offensive","label":"Nous construirons un grand aqueduc depuis les régions voisines. Les débats attendront que les robinets coulent, et les robinets attendront l’aqueduc.","effects":{"popularite":4,"cohesion":-3,"ecologie":-3},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les régions voisines n’aiment pas voir leur eau partir"}],"news":"Le président annonce un grand aqueduc, sans attendre le débat"}]},{"id":"mexique-q-ecologie-train-sud-est","theme":"ecologie","condition":{"gauge":"ecologie","op":">","value":60},"text":"Le train touristique du Sud-Est avance, mais on dit que la jungle, les communautés et les temples sont moins pressés que les ingénieurs. Va-t-on trop vite ?","answers":[{"tone":"franche","label":"Non, mais nous irons plus lentement là où il le faut. Les communautés seront consultées, et les tracés ajustés chaque fois que la nature et le patrimoine l’exigent.","effects":{"ecologie":3,"cohesion":3,"economie":-3},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les consultations locales rassurent les communautés"}],"news":"Train du Sud-Est : le président ralentit sur les zones sensibles"},{"tone":"langue-de-bois","label":"Le train allie développement et respect de l’environnement. Il incarne la modernité tranquille, avec des wagons très tranquilles et un horaire très libre.","effects":{"economie":2,"ecologie":-3},"news":"Le président vante une « modernité tranquille » sur rails"},{"tone":"offensive","label":"Ceux qui s’opposent au train s’opposent au développement du sud. Il passera, et il passera avec la jungle, pas contre elle, sauf quand c’est plus court.","effects":{"economie":5,"popularite":2,"ecologie":-4},"delayed":[{"delay":3,"effects":{"cohesion":-3},"label":"Des communautés locales saisissent la justice"}],"news":"Le président : le train passera, « avec la jungle, sauf quand c’est plus court »"}]},{"id":"mexique-q-international-voisin-tarifs","theme":"international","condition":{"gauge":"international","op":"<","value":40},"text":"Le voisin du nord menace de taxer ce que l’usine monte et le camion transporte. Votre diplomatie est-elle en panne, ou seulement en réunion ?","answers":[{"tone":"franche","label":"Elle est en réunion, mais pas en vacances. Nous négocions pied à pied, et nous protégerons les travailleurs avant les slogans, des deux côtés de la frontière.","effects":{"international":4,"economie":-2,"popularite":-2},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Un accord partiel préserve plusieurs filières"}],"news":"Tarifs : le président assure négocier « pied à pied »"},{"tone":"langue-de-bois","label":"Notre pays est un partenaire fiable, attaché au dialogue et à la stabilité régionale. Les discussions se poursuivent dans un esprit constructif.","effects":{"international":2,"economie":-3},"news":"Tarifs : les discussions se poursuivent « dans un esprit constructif »"},{"tone":"offensive","label":"Nous ne sommes la cour arrière de personne. Si on nous taxe, nous irons chercher des clients ailleurs, à commencer par ceux qui nous respectent.","effects":{"popularite":5,"international":-4,"economie":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"La fierté nationale gagne les marchés et les cafés"}],"news":"Le président : « Nous ne sommes la cour arrière de personne »"}]},{"id":"mexique-q-international-sommet-regional","theme":"international","condition":{"gauge":"international","op":">","value":60},"text":"Le pays est invité à tous les sommets, des plus officiels aux plus décontractés. N’est-ce pas surtout parce que la cuisine y est excellente ?","answers":[{"tone":"franche","label":"La cuisine aide, évidemment. Mais nous sommes invités parce que nous parlons à tout le monde et que nous tenons parole, et cela se mange moins vite.","effects":{"international":4,"budget":-2},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Des accords commerciaux sont négociés entre deux plats"}],"news":"Le président : « Nous sommes invités parce que nous tenons parole »"},{"tone":"langue-de-bois","label":"Notre pays joue un rôle de pont entre les régions du monde. La table est un espace de dialogue, et notre diplomatie est une diplomatie de la table.","effects":{"international":2,"popularite":-2},"news":"Diplomatie : le président revendique une « diplomatie de la table »"},{"tone":"offensive","label":"Il y a des diplomates qui rêvent d’avoir un guacamole à mettre sur la table. Qu’ils nous envient plutôt qu’ils nous critiquent.","effects":{"popularite":4,"international":-3,"assemblee":-2},"news":"Le président : certains diplomates « rêvent d’avoir un guacamole »"}]},{"id":"mexique-q-assemblee-congres-blocage","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":40},"text":"Le Congrès de l’Union traîne sur vos projets : la Chambre veut discuter, le Sénat veut relire, et les partis de la coalition veulent surtout déjeuner. Que faites-vous ?","answers":[{"tone":"franche","label":"J’écouterai chaque groupe, du Mouvement de Renovación Nationale à Travail Uni, et je ferai des compromis réels, pas seulement des invitations au déjeuner.","effects":{"assemblee":5,"budget":-3,"popularite":-2},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les commissions avancent enfin sur les textes en retard"}],"news":"Congrès : le président promet de vrais compromis, pas seulement des déjeuners"},{"tone":"langue-de-bois","label":"Le Congrès est le cœur battant de notre démocratie. Son rythme est celui de la délibération, et le mien celui de la patience, deux rythmes qui se rejoignent.","effects":{"assemblee":2,"popularite":-2},"news":"Le président salue le « cœur battant » d’un Congrès qui bat lentement"},{"tone":"offensive","label":"Si le Congrès ne veut pas voter, j’en appellerai à une consultation populaire. Le peuple est moins long à déjeuner que ses représentants.","effects":{"popularite":5,"assemblee":-5,"international":-2},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Les alliés du Congrès froncent les sourcils"}],"news":"Le président menace le Congrès d’une consultation populaire"}]},{"id":"mexique-q-assemblee-majorite-large","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":65},"text":"Votre majorité au Congrès est si large qu’on se demande si l’opposition tient dans un seul ascenseur. Vous reste-t-il encore des contre-pouvoirs, ou seulement des applaudissements ?","answers":[{"tone":"franche","label":"Une majorité large est un risque autant qu’une chance. Je veux des commissions ouvertes, des rapports contradictoires et des débats qui durent.","effects":{"cohesion":4,"popularite":2,"assemblee":-3},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les observateurs saluent l’ouverture du Congrès"}],"news":"Le président promet des débats ouverts malgré sa large majorité"},{"tone":"langue-de-bois","label":"La majorité traduit la volonté du peuple, et l’opposition continuera à s’exprimer dans les formes, avec un ascenseur adapté si nécessaire.","effects":{"assemblee":2,"cohesion":-2},"news":"Le président promet « un ascenseur adapté » à l’opposition"},{"tone":"offensive","label":"Le peuple a choisi, et il n’a pas choisi l’ascenseur. L’opposition aura toute liberté de contester, dès qu’elle aura une idée plus grande que son hall d’entrée.","effects":{"popularite":4,"cohesion":-3,"international":-2},"news":"Le président à l’opposition : « Une idée plus grande que votre hall »"}]},{"id":"mexique-q-crise-secheresse-capitale","theme":"crise","crisisId":"mexique-secheresse-capitale","text":"La capitale est en alerte sécheresse : des quartiers reçoivent l’eau par camion-citerne et des familles remplissent des seaux à l’aube. Où est l’État ?","answers":[{"tone":"franche","label":"L’État est dans les camions-citernes, mais il doit aussi être dans les tuyaux. Aujourd’hui, des citernes ; demain, un réseau qui ne perd plus un litre sur trois.","effects":{"pouvoirAchat":3,"popularite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"ecologie":2},"label":"Premières fuites réparées dans les quartiers prioritaires"}],"news":"Sécheresse : « L’État est dans les camions-citernes », dit le président"},{"tone":"langue-de-bois","label":"Une cellule de crise suit la situation hydrique avec attention. L’eau reviendra, comme elle revient toujours, quoique parfois avec un peu de retard.","effects":{"popularite":-3,"cohesion":2},"news":"Une cellule de crise « suit la situation hydrique avec attention »"},{"tone":"offensive","label":"Les grands consommateurs industriels devront réduire leurs prélèvements, et les piscines privées apprendront la sobriété. L’eau du peuple passe avant celle des terrasses.","effects":{"pouvoirAchat":4,"popularite":3,"economie":-4},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les industriels dénoncent une mesure précipitée"}],"news":"Le président rationne les gros consommateurs : « L’eau du peuple d’abord »"}]},{"id":"mexique-q-crise-seisme-capitale","theme":"crise","crisisId":"mexique-seisme-capitale","text":"Un séisme a secoué la capitale. Des immeubles sont fissurés, des quartiers évacués, et chaque habitant se souvient des précédents. Quelle est votre priorité ?","answers":[{"tone":"franche","label":"Les personnes d’abord : sauvetage, logements d’urgence, contrôle de chaque bâtiment. Le reste attendra, y compris les photos et les discours.","effects":{"popularite":4,"cohesion":3,"budget":-5},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les voisins s’organisent en brigades de solidarité"}],"news":"Séisme : le président place les personnes avant « les photos et les discours »"},{"tone":"langue-de-bois","label":"Les protocoles de protection civile ont été activés dans l’ordre prévu. Les évaluations des dommages se poursuivent, conformément à la procédure.","effects":{"securite":2,"popularite":-3},"news":"Séisme : les protocoles ont été activés « dans l’ordre prévu »"},{"tone":"offensive","label":"Nous allons vérifier chaque permis de construire des vingt dernières années et sanctionner les responsables de constructions défectueuses, quels qu’ils soient.","effects":{"popularite":4,"securite":3,"economie":-3,"assemblee":-3},"news":"Le président exige un audit des permis de construire après le séisme"}]},{"id":"mexique-q-crise-ouragan-pacifique","theme":"crise","crisisId":"mexique-ouragan-pacifique","text":"Un ouragan frappe la côte du Pacifique : des stations balnéaires dévastées, des pêcheurs sans bateau, des routes coupées. Comment aidez-vous les sinistrés et leurs communes ?","answers":[{"tone":"franche","label":"Une aide directe aux familles et aux pêcheurs, versée sans passer par dix guichets. Les routes seront rouvertes en priorité, pour que l’aide arrive.","effects":{"cohesion":4,"popularite":2,"budget":-5},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les ports reprennent doucement leur activité"}],"news":"Ouragan : aide directe aux familles et aux pêcheurs, sans dix guichets"},{"tone":"langue-de-bois","label":"Les services de protection civile sont mobilisés et l’évaluation des dégâts est en cours. Le gouvernement reste aux côtés des communes sinistrées, de loin comme de près.","effects":{"securite":2,"popularite":-3},"news":"Ouragan : le gouvernement « reste aux côtés des communes sinistrées »"},{"tone":"offensive","label":"Nous allons reconstruire mieux et plus haut, avec des normes qui ne s’envolent pas au premier vent. Les promoteurs de façade seront priés de rendre des comptes.","effects":{"ecologie":3,"popularite":3,"economie":-3,"assemblee":-2},"news":"Le président veut reconstruire « mieux et plus haut » sur la côte"}]},{"id":"mexique-q-crise-tension-frontiere-nord","theme":"crise","crisisId":"mexique-tension-frontiere-nord","text":"À la frontière du nord, des files de camions s’étirent sur des kilomètres et le ton monte entre les deux capitales. Gardez-vous votre calme ou haussez-vous le ton ?","answers":[{"tone":"franche","label":"Je garde mon calme, mais je ne cède pas. Nous protégerons les chauffeurs, les travailleurs et les migrants, et nous demanderons un traitement digne pour tous.","effects":{"international":3,"popularite":2,"economie":-3},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les files de camions commencent à se résorber"}],"news":"Frontière nord : le président garde son calme et réclame « un traitement digne »"},{"tone":"langue-de-bois","label":"Les deux pays sont liés par l’histoire, la géographie et le commerce. Un dialogue franc et respectueux permettra de dépasser les malentendus.","effects":{"international":2,"popularite":-3},"news":"Frontière : « un dialogue franc et respectueux », annonce le président"},{"tone":"offensive","label":"Nous ne céderons pas à la pression. Si les camions attendent, ce sont aussi leurs usines et leurs rayons de supermarché qui attendent avec eux.","effects":{"popularite":5,"international":-4,"economie":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Plusieurs filières d’exportation se retrouvent à l’arrêt"}],"news":"Le président : « Leurs rayons de supermarché attendront avec nos camions »"}]},{"id":"mexique-q-crise-conference-matinale","theme":"crise","crisisId":"mexique-conference-matinale-derape","text":"Votre conférence matinale a dérapé : une réponse trop longue a tourné à la polémique, et trois ministères ont démenti vos chiffres avant midi. Que s’est-il passé ?","answers":[{"tone":"franche","label":"J’ai parlé trop vite et mal vérifié mes chiffres. Je corrigerai en public, demain, avec les bons documents et sans improviser sur l’inflation.","effects":{"popularite":3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"La correction publique est jugée honnête et plutôt drôle"}],"news":"Le président reconnaît ses chiffres erronés et promet de corriger demain"},{"tone":"langue-de-bois","label":"Les chiffres cités relevaient de projections préliminaires, et les ministères ont bien voulu rappeler la rigueur qui nous anime, chacun à sa manière.","effects":{"popularite":2,"economie":-2,"assemblee":-2},"news":"Le président parle de « projections préliminaires » et de rigueur partagée"},{"tone":"offensive","label":"Les chiffres sont justes, ce sont les démentis qui sont faux. Ceux qui m’opposent des tableaux n’ont qu’à les montrer au peuple, en quatre heures.","effects":{"popularite":4,"cohesion":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Les agences de notation haussent un sourcil"}],"news":"Le président maintient ses chiffres : « Ce sont les démentis qui sont faux »"}]},{"id":"mexique-q-crise-violence-region","theme":"crise","crisisId":"mexique-cartel-violence-region","text":"Une région connaît une flambée de violence liée au crime organisé : des familles déplacées, des écoles fermées, des commerçants contraints de payer. Que dites-vous aux habitants ?","answers":[{"tone":"franche","label":"Que l’État reviendra et restera. Je ne promets pas de miracle : je promets de protéger d’abord les écoles, les commerces et les familles déplacées.","effects":{"securite":3,"popularite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les écoles rouvrent sous protection locale"}],"news":"Violence régionale : le président promet de protéger écoles, commerces et familles"},{"tone":"langue-de-bois","label":"Le gouvernement est pleinement mobilisé aux côtés des autorités locales. Une stratégie coordonnée et durable est en cours de déploiement dans la région.","effects":{"securite":2,"popularite":-3},"news":"Violence régionale : le gouvernement « pleinement mobilisé »"},{"tone":"offensive","label":"Je ne négocierai pas avec ceux qui rançonnent des familles. Les renforts arrivent, avec des enquêteurs et des juges, pas seulement des uniformes.","effects":{"securite":5,"budget":-3,"cohesion":-3},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Des ONG demandent des garanties pour les droits des habitants"}],"news":"Le président envoie des renforts, avec « des enquêteurs et des juges »"}]},{"id":"mexique-q-crise-generale-semaine-noire","theme":"crise","text":"Trois urgences en trois jours : une route inondée, une grève de transporteurs, une panne de courant en pleine finale de football. Le gouvernement a-t-il perdu le fil ?","answers":[{"tone":"franche","label":"Quand tout arrive en même temps, on s’occupe d’abord de ce qui touche le plus de monde. La finale de football passera donc en troisième.","effects":{"popularite":3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les transporteurs reprennent le dialogue"}],"news":"Le président place la finale de football en troisième urgence"},{"tone":"langue-de-bois","label":"Le gouvernement est mobilisé sur tous les fronts, avec la sérénité de ceux qui ont un plan, même quand il est dans un tiroir.","effects":{"popularite":2,"economie":-2},"news":"Le gouvernement se dit mobilisé « sur tous les fronts »"},{"tone":"offensive","label":"Le pays a vu pire, et il en rira bientôt. Que les prophètes de malheur proposent leur plan avant que la lumière ne revienne.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"news":"Le président aux critiques : « Proposez un plan avant le retour du courant »"}]},{"id":"mexique-q-scandale-traiteur-conference","theme":"scandale","text":"Le traiteur des conférences matinales appartient au beau-frère d’un secrétaire d’État, et ses tamales sont facturés comme du caviar. Pouvez-vous nous expliquer cette cuisine ?","answers":[{"tone":"franche","label":"Je n’aime pas cette facture, et je demande un audit des marchés publics concernés. Si le beau-frère a vendu trop cher, il remboursera.","effects":{"popularite":4,"assemblee":-3},"delayed":[{"delay":3,"effects":{"budget":2},"label":"L’audit récupère une partie des sommes"}],"news":"Tamales facturés « comme du caviar » : le président ordonne un audit"},{"tone":"langue-de-bois","label":"Les procédures de passation des marchés sont respectées. Le prix reflète une qualité d’exception, cela dit sans commentaire sur le piment.","effects":{"popularite":-3,"assemblee":2},"news":"Le gouvernement défend le prix des tamales, « qualité d’exception »"},{"tone":"offensive","label":"On attaque un cuisinier parce qu’il a de la famille. Dans ce pays, on ne juge pas un tamale sur son arbre généalogique, mais sur sa farce.","effects":{"popularite":3,"cohesion":-3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Un journal publie les factures d’un second traiteur"}],"news":"Le président défend le traiteur : « On juge un tamale sur sa farce »"}]},{"id":"mexique-q-scandale-audio-chauffeur","theme":"scandale","text":"Un enregistrement fuité montre un conseiller qui explique à son chauffeur comment attribuer des licences de transport à ses amis. Découvrez-vous l’affaire en même temps que nous ?","answers":[{"tone":"franche","label":"Je l’ai découvert hier soir, et le conseiller a quitté ses fonctions ce matin. Les licences seront réexaminées une à une, avec les amis.","effects":{"popularite":4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les alliés du conseiller regrettent une décision rapide"}],"news":"Fuite audio : le conseiller écarté, les licences de transport réexaminées"},{"tone":"langue-de-bois","label":"L’enregistrement est en cours d’authentification. Le gouvernement rappelle sa confiance dans ses équipes, qui l’expriment en retour, de manière enregistrée.","effects":{"assemblee":2,"popularite":-3},"news":"Fuite audio : le gouvernement attend l’« authentification » de l’enregistrement"},{"tone":"offensive","label":"Une fuite, c’est d’abord un délit, et je demande qu’on retrouve celui qui a enregistré. Le chauffeur, lui, a surtout bien conduit.","effects":{"popularite":2,"assemblee":3,"cohesion":-4},"delayed":[{"delay":3,"effects":{"popularite":-4},"label":"La presse relance l’affaire avec de nouvelles pièces"}],"news":"Le président s’inquiète de la fuite plus que du contenu de l’audio"}]},{"id":"mexique-q-scandale-conflit-interets-mine","theme":"scandale","text":"Un sénateur de votre camp possède des parts dans une entreprise qui vient de décrocher un contrat d’infrastructure. Il affirme n’avoir « vu le contrat qu’en passant ». Le croyez-vous ?","answers":[{"tone":"franche","label":"Je crois en la transparence, pas en la chance. Il rendra publiques toutes ses participations, et le contrat sera rouvert si le doute demeure.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"delayed":[{"delay":3,"effects":{"budget":2},"label":"Le contrat est renégocié à un meilleur prix"}],"news":"Conflit d’intérêts : le président exige la transparence d’un sénateur allié"},{"tone":"langue-de-bois","label":"Le sénateur a déclaré ses intérêts conformément à la règle. Le contrat est conforme aux procédures, et la comptabilité n’en sort que plus claire.","effects":{"assemblee":3,"popularite":-3},"news":"Le gouvernement juge le contrat du sénateur « conforme aux procédures »"},{"tone":"offensive","label":"On cherche des coupables là où il n’y a que des entrepreneurs. Que ceux qui n’ont jamais eu une part dans une entreprise lèvent la main.","effects":{"assemblee":4,"popularite":2,"cohesion":-4},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Des élus de la majorité demandent des explications"}],"news":"Le président : « Que celui qui n’a jamais eu de parts lève la main »"}]},{"id":"mexique-q-culture-jour-des-morts","theme":"cohesion","text":"Le pays prépare ses offrandes pour la fête des morts, entre fleurs de souci et pain sucré. Que mettriez-vous sur l’autel de votre gouvernement ?","answers":[{"tone":"franche","label":"Les promesses non tenues, avec un peu de respect. Une bonne offrande commence par reconnaître ce qu’on n’a pas réussi, avant de promettre mieux.","effects":{"popularite":4,"cohesion":3,"assemblee":-3},"news":"Le président met « les promesses non tenues » sur l’autel du gouvernement"},{"tone":"langue-de-bois","label":"Des fleurs, du pain, et une photographie de l’unité nationale. Notre tradition est un trésor qui rassemble les générations autour d’une même table.","effects":{"cohesion":2,"popularite":-2},"news":"Le président dépose « une photographie de l’unité nationale »"},{"tone":"offensive","label":"Une pile de sondages, une photo de l’opposition et un bon piment. Les ancêtres apprécieront que les vivants débattent encore.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"La fête reste respectée malgré l’humour du président"}],"news":"Le président offre un piment à l’opposition sur l’autel du gouvernement"}]},{"id":"mexique-q-culture-football-mondial","theme":"popularite","text":"La sélection nationale de football affronte un match décisif et la moitié du pays a posé sa journée. Vos ministres doivent-ils travailler pendant le match ?","answers":[{"tone":"franche","label":"Non. Un pays qui vibre pour son équipe vaut bien un conseil des ministres sans ordre du jour. Les dossiers seront fidèles au poste à la mi-temps.","effects":{"popularite":5,"economie":-3},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"La défaite de la sélection fait chuter le moral national"}],"news":"Le président suspend le conseil des ministres pendant le match"},{"tone":"langue-de-bois","label":"Le sport est un vecteur de cohésion. Les ministres feront preuve de responsabilité, de présence et de discrétion, et auront chacun leur écran, avec le son coupé.","effects":{"cohesion":2,"popularite":-2},"news":"Les ministres suivront le match « avec le son coupé »"},{"tone":"offensive","label":"Les ministres travailleront, et je regarderai le match en leur nom. Quelqu’un doit bien représenter le gouvernement sur le canapé.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"news":"Le président regardera le match « au nom des ministres »"}]},{"id":"mexique-q-culture-ahorita-retard","theme":"popularite","text":"Dans ce pays, « tout de suite » peut signifier dans dix minutes, dans dix jours ou après la fête. Vos promesses de réforme sont-elles à l’heure « tout de suite » ?","answers":[{"tone":"franche","label":"Certaines le sont, d’autres sont à l’heure du dimanche. Je préfère vous donner un calendrier précis, quitte à le voir contesté par chaque mardi.","effects":{"popularite":4,"assemblee":-2},"delayed":[{"delay":3,"effects":{"popularite":2},"label":"Le calendrier tient pour deux réformes sur trois"}],"news":"Le président promet un calendrier précis, « quitte à être contesté »"},{"tone":"langue-de-bois","label":"Le gouvernement avance à un rythme soutenu mais serein, dans l’esprit de notre culture, qui sait que les belles choses se préparent avec soin.","effects":{"popularite":2,"economie":-2},"news":"Le gouvernement avance à « un rythme soutenu mais serein »"},{"tone":"offensive","label":"Si « tout de suite » veut dire bientôt, alors mes ministres sont déjà en retard sur moi. Je rappelle que ce retard est une marque de distinction.","effects":{"popularite":4,"cohesion":-2,"assemblee":-3},"news":"Le président accuse ses ministres d’être « en retard sur lui »"}]},{"id":"mexique-q-culture-langues-indigenes","theme":"cohesion","text":"Des dizaines de langues autochtones sont parlées dans le pays, mais l’administration préfère encore une seule langue pour ses formulaires. Quand le guichet écoutera-t-il le village ?","answers":[{"tone":"franche","label":"Les services publics seront traduits dans les principales langues, avec des interprètes locaux. Une démocratie qui n’écoute qu’en une langue écoute mal.","effects":{"cohesion":5,"popularite":2,"budget":-4},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les premiers guichets bilingues ouvrent dans trois régions"}],"news":"Le président annonce des guichets publics en langues autochtones"},{"tone":"langue-de-bois","label":"La diversité linguistique est une richesse immense, que le gouvernement soutient avec enthousiasme et un groupe de travail interministériel.","effects":{"cohesion":2,"popularite":-2},"news":"Langues autochtones : un groupe de travail interministériel est lancé"},{"tone":"offensive","label":"Les formulaires seront simplifiés dans toutes les langues, et ceux qui les remplissent mal pourront enfin les remplir dans la langue qu’ils veulent.","effects":{"cohesion":3,"popularite":3,"economie":-3,"assemblee":-2},"news":"Le président promet des formulaires simplifiés « dans toutes les langues »"}]},{"id":"mexique-q-culture-tourisme-algues","theme":"international","text":"Les plages des Caraïbes croulent sous les algues brunes, et les touristes demandent si le sable est livré avec. Votre pays peut-il perdre ses vacances sans perdre sa dignité ?","answers":[{"tone":"franche","label":"Nous financerons le ramassage et la recherche de nouveaux usages, avec les hôteliers et les pêcheurs. L’algue est un problème avant d’être un décor.","effects":{"ecologie":3,"economie":2,"budget":-5},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Une filière de valorisation des algues voit le jour"}],"news":"Algues : le président finance le ramassage avec hôteliers et pêcheurs"},{"tone":"langue-de-bois","label":"Le tourisme demeure un atout essentiel, et le gouvernement suit l’évolution du phénomène avec la plus grande attention et la plus grande distance.","effects":{"economie":2,"popularite":-3},"news":"Algues : le gouvernement suit le phénomène « avec attention »"},{"tone":"offensive","label":"Nos plages sont les plus belles du monde, algues comprises. Venez les voir avec les algues : c’est du sable avec un supplément de caractère.","effects":{"popularite":3,"international":3,"ecologie":-3,"economie":-2},"delayed":[{"delay":2,"effects":{"international":-2},"label":"Les agences de voyage jugent la campagne audacieuse"}],"news":"Le président lance une campagne : « Du sable avec du caractère »"}]},{"id":"mexique-q-culture-cuisine-patrimoine","theme":"international","text":"Le piment, le maïs et le chocolat font du pays une puissance gastronomique. Pourquoi ne pas faire de la cuisine un ministère, avec des fourneaux et un budget ?","answers":[{"tone":"franche","label":"Parce qu’un ministère risquerait d’en faire un plat administratif. Je préfère aider les cuisinières de marché et les petits producteurs qui entretiennent ce patrimoine.","effects":{"cohesion":3,"popularite":3,"budget":-4},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les marchés locaux profitent d’un regain de touristes"}],"news":"Le président soutient les cuisinières de marché plutôt qu’un ministère"},{"tone":"langue-de-bois","label":"La gastronomie est un pilier de notre identité et un ambassadeur de notre pays, que nous continuerons de protéger, de valoriser et de déguster.","effects":{"international":2,"popularite":-2},"news":"Le président qualifie la gastronomie d’« ambassadeur du pays »"},{"tone":"offensive","label":"Un ministère de la cuisine, oui, à condition qu’il commence par régler le conflit éternel sur la pâte de maïs. Les négociations dureront des décennies.","effects":{"popularite":4,"international":2,"assemblee":-3,"budget":-2},"news":"Le président : un ministère de la cuisine pour résoudre « le conflit éternel »"}]}]}'),u={pays:e,version:1,textes:s,institutions:n,election:a,lois:i,crises:t,missions:r,presse:o};export{t as crises,u as default,a as election,n as institutions,i as lois,r as missions,e as pays,o as presse,s as textes,l as version};
